use cpal::{BufferSize, StreamConfig};
use cpal::traits::{DeviceTrait, HostTrait};
fn main() {
    let host = cpal::default_host();
    if let Some(device) = host.default_output_device() {
        let config = StreamConfig {
            channels: 2,
            sample_rate: 48000,
            buffer_size: BufferSize::Fixed(256),
